  L5.u64_at RSEGS M' a' w0 -> L5.u64_at RSEGS M' (a' + 8) w1 -> L5.u64_at RSEGS M' (a' + 16) w2 ->
  Z.of_nat (length l) <= 23 -> L5.bytes_at RSEGS M (a + 1) l -> L5.bytes_at RSEGS M' (a' + 1) l.
